const manifest = {
  corpus: { chunks: 24, probes: '10/10' },
  retrieval: { ablated: true },
  rewriting: { vagueGain: 0.22 },
  generation: { moneyGate: '7-day' },
  routing: { tests: '5/5' },
  eval: { gold: 15 },
};
const checks = [
  ['corpus probed', manifest.corpus.probes === '10/10'],
  ['retrieval ablated', manifest.retrieval.ablated === true],
  ['rewriting measured', manifest.rewriting.vagueGain > 0.1],
  ['money gated', manifest.generation.moneyGate === '7-day'],
  ['router tested', manifest.routing.tests === '5/5'],
  ['gold sized', manifest.eval.gold >= 12],
];
for (const [label, ok] of checks) console.log((ok ? 'PASS ' : 'FAIL ') + label);
console.log(checks.every(([, ok]) => ok) ? 'manifest sound' : 'manifest BROKEN');

